-- ============================================================
-- Sales Project | MySQL one-click import
-- Kaise chalana hai: MySQL Workbench > File > Open SQL Script > ye file
-- chuno > upar bijli (lightning) icon dabao. Bas. CSV import nahi karna.
-- ============================================================
DROP DATABASE IF EXISTS sales_project;
CREATE DATABASE sales_project;
USE sales_project;

CREATE TABLE customers_raw (
  customer_id VARCHAR(10), customer_name VARCHAR(100), city VARCHAR(50), state VARCHAR(50),
  region VARCHAR(20), segment VARCHAR(20), signup_date DATE, email VARCHAR(120));
CREATE TABLE products_raw (
  product_id VARCHAR(10), product_name VARCHAR(100), category VARCHAR(50),
  sub_category VARCHAR(50), unit_cost DECIMAL(12,2), list_price DECIMAL(12,2));
CREATE TABLE orders_raw (
  order_id VARCHAR(15), customer_id VARCHAR(10), order_date DATE, ship_date DATE,
  ship_mode VARCHAR(20), sales_channel VARCHAR(20), payment_mode VARCHAR(20),
  order_status VARCHAR(20), region VARCHAR(20));
CREATE TABLE order_items_raw (
  order_item_id VARCHAR(12), order_id VARCHAR(15), product_id VARCHAR(10),
  quantity INT, discount_pct DECIMAL(5,2));

-- customers: 2500 rows
-- products: 72 rows
-- orders: 14060 rows
-- order_items: 23469 rows

-- ===== Sanity check (expected: 2500 / 72 / 14060 / 23469) =====
SELECT 'customers' AS t, COUNT(*) AS n FROM customers_raw UNION ALL
SELECT 'products', COUNT(*) FROM products_raw UNION ALL
SELECT 'orders', COUNT(*) FROM orders_raw UNION ALL
SELECT 'order_items', COUNT(*) FROM order_items_raw;
